use fuzzy_matcher::{skim::SkimMatcherV2, FuzzyMatcher};
use itertools::Itertools;
use serde::Serialize;
use crate::graph::{Graph, GraphContext};
use crate::model::node::{NodeIter, NodePointer};
use crate::model::{Key, NodeId};
use crate::selector::Selector;

#[derive(Debug, Clone, Serialize)]
pub struct ParentDocumentInfo {
    pub key: String,
    pub title: String,
    pub section_path: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct FindResult {
    pub key: String,
    pub title: String,
    pub display_title: String,
    pub is_root: bool,
    pub incoming_refs: usize,
    pub outgoing_refs: usize,
    pub parent_documents: Vec<ParentDocumentInfo>,
}

#[derive(Debug, Clone, Serialize)]
pub struct FindOutput {
    pub query: Option<String>,
    pub limit: Option<usize>,
    pub total: usize,
    pub results: Vec<FindResult>,
}

#[derive(Debug, Clone, Default)]
pub struct FindOptions {
    pub query: Option<String>,
    pub roots: bool,
    pub refs_to: Option<Key>,
    pub refs_from: Option<Key>,
    pub selector: Selector,
    pub limit: Option<usize>,
    pub metadata_filters: Vec<(String, String)>,
}

pub struct DocumentFinder<'a> {
    graph: &'a Graph,
}

impl<'a> DocumentFinder<'a> {
    pub fn new(graph: &'a Graph) -> Self {
        Self { graph }
    }

    pub fn find(&self, options: &FindOptions) -> FindOutput {
        let matcher = SkimMatcherV2::default();

        let candidate_set = if options.selector.is_empty() {
            None
        } else {
            Some(options.selector.resolve(self.graph))
        };

        let mut results: Vec<(Key, i64)> = self
            .graph
            .keys()
            .into_iter()
            .filter_map(|key| {
                if let Some(set) = &candidate_set {
                    if !set.contains(&key) {
                        return None;
                    }
                }
                if options.roots && !self.is_root(&key) {
                    return None;
                }
                if let Some(ref target) = options.refs_to {
                    if !self.references(&key, target) {
                        return None;
                    }
                }
                if let Some(ref source) = options.refs_from {
                    if !self.references(source, &key) {
                        return None;
                    }
                }

                if !options.metadata_filters.is_empty()
                    && !self.metadata_matches(&key, &options.metadata_filters)
                {
                    return None;
                }

                let title = self.graph.get_key_title(&key).unwrap_or_default();
                let search_text = format!("{} {}", key, title);

                let score = options
                    .query
                    .as_ref()
                    .map(|q| matcher.fuzzy_match(&search_text, q).unwrap_or(0))
                    .unwrap_or(self.node_rank(&key) as i64);

                if options.query.is_some() && score == 0 {
                    return None;
                }

                Some((key, score))
            })
            .collect();

        results.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

        let total = results.len();
        let results: Vec<FindResult> = if let Some(limit) = options.limit {
            results
                .into_iter()
                .take(limit)
                .map(|(key, _)| self.build_result(&key))
                .collect()
        } else {
            results
                .into_iter()
                .map(|(key, _)| self.build_result(&key))
                .collect()
        };

        let limit = options.limit.filter(|&l| l < total);

        FindOutput {
            query: options.query.clone(),
            limit,
            total,
            results,
        }
    }

    fn build_result(&self, key: &Key) -> FindResult {
        let title = self.graph.get_key_title(key).unwrap_or_default();
        let parent_documents = self.get_parent_documents(key);
        let display_title = Self::render_display_title(&title, &parent_documents);

        FindResult {
            key: key.to_string(),
            title,
            display_title,
            is_root: self.is_root(key),
            incoming_refs: self.graph.get_block_references_to(key).len()
                + self.graph.get_inline_references_to(key).len(),
            outgoing_refs: self.graph.get_block_references_in(key).len(),
            parent_documents,
        }
    }

    fn render_display_title(title: &str, parent_documents: &[ParentDocumentInfo]) -> String {
        if parent_documents.is_empty() {
            title.to_string()
        } else {
            let parents = parent_documents
                .iter()
                .map(|p| format!("↖{}", p.title))
                .collect::<Vec<_>>()
                .join(" ");
            format!("{} {}", title, parents)
        }
    }

    fn is_root(&self, key: &Key) -> bool {
        self.graph.get_block_references_to(key).is_empty()
    }

    fn node_rank(&self, key: &Key) -> usize {
        self.graph.get_inline_references_to(key).len()
            + self.graph.get_block_references_to(key).len()
    }

    fn references(&self, source: &Key, target: &Key) -> bool {
        let block_refs = self.graph.get_block_references_in(source);
        for ref_id in block_refs {
            if let Some(ref_key) = self.graph.graph_node(ref_id).ref_key() {
                if &ref_key == target {
                    return true;
                }
            }
        }

        if let Some(node_id) = self.graph.get_node_id(source) {
            let sub_nodes = self.graph.node(node_id).get_all_sub_nodes();
            for sub_node_id in sub_nodes {
                if let Some(line_id) = self.graph.graph_node(sub_node_id).line_id() {
                    let line = self.graph.get_line(line_id);
                    for ref_key in line.ref_keys() {
                        if &ref_key == target {
                            return true;
                        }
                    }
                }
            }
        }

        false
    }

    fn get_parent_documents(&self, key: &Key) -> Vec<ParentDocumentInfo> {
        let refs = self.graph.get_block_references_to(key);
        let mut parents = Vec::new();

        for ref_id in refs {
            let node = self.graph.node(ref_id);

            if let Some(doc_node) = node.to_document() {
                if let Some(doc_key) = doc_node.document_key() {
                    let title = self
                        .graph
                        .get_key_title(&doc_key)
                        .unwrap_or_else(|| doc_key.to_string());

                    let section_path = self.get_section_path(ref_id);

                    parents.push(ParentDocumentInfo {
                        key: doc_key.to_string(),
                        title,
                        section_path,
                    });
                }
            }
        }

        parents.into_iter().unique_by(|p| p.key.clone()).collect()
    }

    fn get_section_path(&self, node_id: NodeId) -> Vec<String> {
        let mut path = Vec::new();
        let mut current = self.graph.node(node_id);

        while let Some(parent) = current.to_parent() {
            if parent.is_section()
                && parent
                    .to_parent()
                    .map(|p| p.is_document())
                    .unwrap_or(true)
            {
                let text = parent.plain_text().trim().to_string();
                path.push(text);
            }
            if parent.is_document() {
                break;
            }
            current = parent;
        }
        path
    }

    fn metadata_matches(&self, key: &Key, filters: &[(String, String)]) -> bool {
        let raw = match self.graph.get_metadata(key) {
            Some(s) => s,
            None => return false,
        };
        let val: serde_yaml::Value = match serde_yaml::from_str(raw) {
            Ok(v) => v,
            _ => return false,
        };
        filters.iter().all(|(k, v)| {
            val.get(k.as_str())
                .and_then(|node| match node {
                    serde_yaml::Value::String(s) => Some(s.as_str() == v.as_str()),
                    serde_yaml::Value::Bool(b) => Some(b.to_string() == *v),
                    serde_yaml::Value::Number(n) => Some(n.to_string() == *v),
                    serde_yaml::Value::Sequence(items) => Some(
                        items
                            .iter()
                            .any(|i| i.as_str().map(|s| s == v.as_str()).unwrap_or(false)),
                    ),
                    _ => Some(false),
                })
                .unwrap_or(false)
        })
    }
}

use std::sync::Once;

use indoc::indoc;
use pretty_assertions::assert_str_eq;

use liwe::model::config::MarkdownOptions;
use liwe::{
    graph::Graph,
    state::{from_indoc, to_indoc},
};

static INIT: Once = Once::new();

fn setup() {
    INIT.call_once(|| {
        env_logger::builder().init();
    });
}

fn bare_options() -> MarkdownOptions {
    MarkdownOptions {
        bare_frontmatter: true,
        ..Default::default()
    }
}

#[test]
fn reader_detects_bare_title_block() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Foo
            status: ready

            # Body
            "}),
        bare_options(),
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    // The metadata should have been parsed — the output should have fenced front matter
    // since we're exporting with bare_frontmatter=true, it should be bare again
    assert!(content.starts_with("title: Foo"));
}

#[test]
fn reader_skips_when_disabled() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Foo
            status: ready

            # Body
            "}),
        MarkdownOptions::default(), // bare_frontmatter = false
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    // Without bare_frontmatter, "title: Foo" is just body text, no metadata parsed
    // So no frontmatter block in output
    assert!(!content.contains("---"));
}

#[test]
fn reader_skips_when_no_title_first_line() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            date: 2024-01-01
            title: Foo

            # Body
            "}),
        bare_options(),
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    // First line isn't "title: " so no metadata parsed
    assert!(!content.contains("---"));
}

#[test]
fn reader_does_not_misparse_prose() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            This is a paragraph.

            # H
            "}),
        bare_options(),
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    assert!(!content.contains("---"));
}

#[test]
fn reader_still_handles_fenced() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            ---
            title: Fenced
            ---

            # Header
            "}),
        bare_options(),
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    // With bare_frontmatter enabled, writer should emit bare format
    assert!(content.starts_with("title: Fenced"));
    assert!(!content.starts_with("---"));
}

#[test]
fn writer_emits_bare_when_enabled() {
    setup();

    let input = indoc! {"
        title: Foo

        # Body
    "};

    let graph = Graph::import(
        &from_indoc(input),
        bare_options(),
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    assert!(content.starts_with("title: Foo"));
    assert!(!content.starts_with("---"));
    assert!(content.contains("# Body"));
}

#[test]
fn writer_emits_fenced_when_disabled() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            ---
            title: Foo
            ---

            # Body
            "}),
        MarkdownOptions::default(),
        None,
    );

    let state = graph.export();
    let content = state.values().next().unwrap();
    assert!(content.starts_with("---\ntitle: Foo\n---"));
}

#[test]
fn frontmatter_title_works_with_bare() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            [old](2)
            _
            title: Bare Title
            status: ready

            # Header
            "}),
        bare_options(),
        Some("title".to_string()),
    );

    let normalized = to_indoc(&graph.export());

    assert_str_eq!(
        indoc! {"
            [Bare Title](2)
            _
            title: Bare Title
            status: ready

            # Header
            "},
        normalized
    );
}

use std::borrow::Cow;

use crate::graph::Reader;
use crate::model::config::MarkdownOptions;
use crate::model::document::Document;

pub mod reader;

use reader::MarkdownEventsReader;
pub struct MarkdownReader {}

pub mod writer;

impl Default for MarkdownReader {
    fn default() -> Self {
        Self::new()
    }
}

impl MarkdownReader {
    pub fn new() -> MarkdownReader {
        MarkdownReader {}
    }
}

/// If `bare_frontmatter` is enabled and content starts with `title: ` (but
/// not `---`), wrap the leading header block in `---` fences so the
/// downstream pulldown-cmark MetadataBlock machinery picks it up.
pub fn wrap_bare_frontmatter(content: &str) -> Cow<'_, str> {
    // Already fenced — leave alone.
    if content.starts_with("---") {
        return Cow::Borrowed(content);
    }

    // Must start with `title: `.
    if !content.starts_with("title: ") {
        return Cow::Borrowed(content);
    }

    // Find first true blank line (\n\n or \r\n\r\n).
    let (header, rest) = if let Some(pos) = content.find("\n\n") {
        (&content[..pos], &content[pos + 2..])
    } else if let Some(pos) = content.find("\r\n\r\n") {
        (&content[..pos], &content[pos + 4..])
    } else {
        // No blank line — entire content is header.
        (content.trim_end(), "")
    };

    if rest.is_empty() {
        let cleaned_header: String = header
            .lines()
            .filter(|l| !l.starts_with(' '))
            .collect::<Vec<_>>()
            .join("\n");
        Cow::Owned(format!("---\n{}\n---\n", cleaned_header))
    } else {
        let cleaned_header: String = header
            .lines()
            .filter(|l| !l.starts_with(' '))
            .collect::<Vec<_>>()
            .join("\n");
        Cow::Owned(format!("---\n{}\n---\n\n{}", cleaned_header, rest))
    }
}

impl Reader for MarkdownReader {
    fn document(&self, content: &str, markdown_options: &MarkdownOptions) -> Document {
        let effective = if markdown_options.bare_frontmatter {
            wrap_bare_frontmatter(content)
        } else {
            Cow::Borrowed(content)
        };

        let mut reader = MarkdownEventsReader::new_with_options(markdown_options);
        reader.read(&effective);

        Document {
            blocks: reader.blocks(),
            metadata: reader.metadata(),
        }
    }
}

