#[test]
fn bare_frontmatter_sequence_value_matches() {
    // Regression: `iwe find --meta depends=foo` returned no results for
    // documents whose front matter used the bare (non-fenced) format with
    // a YAML sequence such as `depends:\n  - foo`. The bare-frontmatter
    // wrapping logic was filtering out indented continuation lines, which
    // turned `depends:` into a null-valued field before the metadata
    // filter ever ran.
    let bare_options = MarkdownOptions {
        bare_frontmatter: true,
        ..Default::default()
    };
    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Task A
            depends:
              - foo
              - bar

            # Task A
        "}),
        bare_options,
        None,
    );

    let finder = DocumentFinder::new(&graph);
    let options = FindOptions {
        metadata_filters: vec![("depends".to_string(), "foo".to_string())],
        ..Default::default()
    };
    let output = finder.find(&options);
    assert_eq!(output.results.len(), 1);
    assert_eq!(output.results[0].title, "Task A");
}
